mapper.sql:
WHERE quotations.status > 0 AND quotations.company_id IN (SELECT company_id FROM user_companies WHERE user_id = #{userId})

    AND quotations.type = #{filter.type}


    AND quotations.created_by = #{userId}


    AND quotations.customer_id IN (SELECT customer_id FROM customer_cgroups WHERE cgroup_id = #{filter.customerGroupId})


    AND quotations.quotation_date >= #{filter.dateFrom}


    AND quotations.quotation_date <= #{filter.dateTo}


    AND quotations.status = #{filter.status}


    AND (quotations.quotation_code LIKE CONCAT('%', #{filter.searchText}, '%')
    OR customers.customer_code LIKE CONCAT('%', #{filter.searchText}, '%')
    OR customers.name LIKE CONCAT('%', #{filter.searchText}, '%')
    OR customers.name_kh LIKE CONCAT('%', #{filter.searchText}, '%')
    OR (SELECT contact_name FROM customer_contacts WHERE id = quotations.customer_contact_id) LIKE CONCAT('%', #{filter.searchText}, '%')
    )

mapper.select:
SELECT
GROUP BY quotations.id ORDER BY quotations.id ASC
LIMIT #{filter.page}, #{filter.rowsPerPage}

mapper.insert:
INSERT INTO quotation_term_conditions (
    quotation_id,
    term_condition_type_id,
    term_condition_id
) VALUES (
             #{termCondition.quotationId},
             #{termCondition.termConditionTypeId},
             #{termCondition.termConditionId}
         )

mapper.select:
SELECT * FROM ( SELECT qtc.term_condition_type_id AS typeId, tct.name AS typeName, qtc.term_condition_id AS id, tc.name AS name FROM quotation_term_conditions qtc INNER JOIN term_condition_types tct ON tct.id = qtc.term_condition_type_id INNER JOIN term_conditions tc ON tc.id = qtc.term_condition_id WHERE qtc.quotation_id = #{quotationId}
UNION ALL
SELECT tca.term_condition_type_id AS typeId, tct.name AS typeName, IFNULL(tca.term_condition_default_id, 0) AS id, IFNULL(tc.name, '') AS name FROM term_condition_applies tca INNER JOIN term_condition_types tct ON tct.id = tca.term_condition_type_id LEFT JOIN term_conditions tc ON tc.id = tca.term_condition_default_id WHERE tca.is_active = 1 AND tca.module_type_id IN ( SELECT id FROM module_types WHERE status = 1 AND (name = 'Quotation' OR name = 'Quotation (Software)') ) AND EXISTS ( SELECT 1 FROM quotation_term_conditions qtc2 WHERE qtc2.quotation_id = #{quotationId} AND qtc2.term_condition_type_id = tca.term_condition_type_id ) ) AS results GROUP BY typeId

mapper.update:
UPDATE quotations SET


        is_approve = 1,


        is_approve = 0,


approved = NOW(),
approved_by = #{userId}
WHERE id = #{id} AND status > 0;

UPDATE quotations SET
is_close = #{status}
WHERE id = #{id} AND status > 0;

UPDATE quotations
SET share_user = #{params.userIds}
WHERE id = #{params.id}

UPDATE quotations
SET share_except_user = #{params.userIds}
WHERE id = #{params.id}

mapper.select:
SELECT COUNT(*) AS total
FROM (
         SELECT id FROM quotation_details WHERE quotation_id = #{quotationId}
         UNION ALL
         SELECT id FROM quotation_services WHERE quotation_id = #{quotationId}
         UNION ALL
         SELECT id FROM quotation_miscs WHERE quotation_id = #{quotationId}
     ) AS combined

